// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function testFuzz_property(uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        // Initialize the contract: after this, MinSum must be frozen.
        c.Initialized();
        uint256 before = c.MinSum();

        vm.prank(actor);
        try c.SetMinSum(newVal) {
            // Accepted call: MinSum must still be unchanged after initialization.
            assertTrue(c.MinSum() == before, "MinSum changed after initialization");
        } catch {
            // Reverted: MinSum unchanged, rule holds.
            assertTrue(c.MinSum() == before, "MinSum changed after initialization");
        }
    }
}
